package net.officefloor.hq.app.period;

/** A claim add, edit or status change touching a date inside a closed period. */
public class ClosedPeriodException extends Exception {
    public ClosedPeriodException(Period period) {
        super("The period " + period.name() + " is closed: its claims cannot be changed.");
    }
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { countedAt, type Claim } from '../claims/claims';
import { gradeOn, type Person } from '../people/people';
import { claimDue, rateOn, sumDue, type Late, type Rate } from '../rates/rates';
import type { DatedValue } from '../settings/settings';

/** A period on the sheet: a name unique on the sheet and an inclusive from and to date (yyyy-mm-dd). No two
 *  periods overlap. A closed period keeps the due-total fixed when it was closed (null while open), and each
 *  person's due-total fixed then, by person id (empty while open). A soft-closed period keeps them fixed the same
 *  way, while its claims can still be added and changed. */
export type Period = { name: string; from: string; to: string; closed: boolean; closedTotal: string | null;
  personTotals: Record<string, string>; soft: boolean };

export const periodsKey = (sheetId: string) => ['sheet', sheetId, 'periods'] as const;

/** The sheet's periods, earliest first. */
export function usePeriods(sheetId: string) {
  return useQuery({
    queryKey: periodsKey(sheetId),
    queryFn: () => getJson<Period[]>(`/api/sheets/${encodeURIComponent(sheetId)}/periods`),
  });
}

/** The period whose dates contain the date (yyyy-mm-dd), or undefined when none does. */
export function periodOf(periods: Period[], date: string): Period | undefined {
  return periods.find((p) => p.from <= date && date <= p.to);
}

/** A person's due-total for a period: while it is open, the dues (as shown on their rows now) of the person's claims
 *  that counted at the end of its last day (see countedAt) whose date falls in it; once closed or soft-closed, the figure fixed for them then (0.00 for a person
 *  added after). */
export function personPeriodDueTotal(period: Period, person: Person, claims: Claim[], people: Person[], rates: Rate[],
    floor: DatedValue, late: Late): string {
  if (period.closed || period.soft) return period.personTotals?.[String(person.id)] ?? '0.00';
  return sumDue(
    countedAt(claims.filter((c) => c.personId === person.id), people, period.to, late.today)
      .filter((c) => periodOf([period], c.date))
      .map((c) => claimDue(c, rateOn(rates, gradeOn(person, c.date), c.date), floor, late)),
  );
}

/** A period's due-total as shown on its row: the people's due-totals for it (see personPeriodDueTotal) added up. */
export function periodDueTotal(period: Period, claims: Claim[], people: Person[], rates: Rate[], floor: DatedValue,
    late: Late): string {
  return sumDue(people.map((p) => personPeriodDueTotal(period, p, claims, people, rates, floor, late)));
}
] as const;

/** One claim with its status, its due-by and whether it is overdue, who opened it and the buttons that change it
 *  (a steward approves or rejects, with a reason, a PENDING claim, and re-settles a SETTLED one at today's figure). A change the status does not
 *  allow, a settle (or approve) by the user who opened it, or an approve or reject by a clerk, is refused by the server and shown as the claim's error;
 *  so is editing a claim that is no longer a DRAFT, or one whose editor another user holds open (opening the editor locks
 *  the claim until it is saved or cancelled, or the sheet's today changes), or one dated in a closed period (the server refuses those
 *  edits too). A steward re-dates an OPEN or PENDING claim; the server refuses anyone else, a date after its person's
 *  retirement, and a claim or new date inside a closed period. */
function ClaimRow({ sheetId, user, claim, rate }: { sheetId: string; user: string; claim: Claim; rate?: string }) {
  const queryClient = useQueryClient();
  const [editingId, setEditing] = useEditingClaim();
  const [error, setError] = useState('');
  const refused = useLockRefused(claim.id);
  const clearError = () => {
    setError('');
    setLockRefused(claim.id, '');
  };
  const [reason, setReason] = useState('');
  const period = periodOf(usePeriods(sheetId).data ?? [], claim.date);
  const floor = useFloor(sheetId);
  const today = useSheetToday(sheetId);
  const late = useLate(sheetId);
  const selected = useSelectedClaims(sheetId).has(claim.id);
  const others = (usePeople(sheetId).data ?? []).filter((p) => p.id !== claim.personId);
  const [moveTo, setMoveTo] = useState('');
  const [deferUntil, setDeferUntil] = useState('');
  const [redateTo, setRedateTo] = useState('');
  const [splitAmount, setSplitAmount] = useState('');

  const change = useMutation({
    mutationFn: (action: string) =>
      putJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${claim.id}/status`, action === 'reject' ? { user, action, reason } : { user, action }),
    onSuccess: async (_, action) => {
      if (action === 'reject') setReason('');
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
    onError: (e, action) =>
      setError(e instanceof HttpError && (e.status === 409 || e.status === 400) && e.body ? e.body : `Could not ${action} this ${claim.status} claim.`),
  });

  const reassign = useMutation({
    mutationFn: (personId: string) =>
      putJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${claim.id}/reassign`, { user, personId }),
    onSuccess: async () => {
      setMoveTo('');
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
    onError: (e) =>
      setError(e instanceof HttpError && (e.status === 409 || e.status === 400 || e.status === 404) && e.body
        ? e.body : `Could not move this ${claim.status} claim.`),
  });

  const proof = useMutation({
    mutationFn: () =>
      postJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${claim.id}/proof`, { user }),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
    onError: (e) =>
      setError(e instanceof HttpError && (e.status === 409 || e.status === 400 || e.status === 404) && e.body
        ? e.body : `Could not add a proof to this ${claim.status} claim.`),
  });

  const defer = useMutation({
    mutationFn: (until: string) =>
      putJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${claim.id}/defer`, { user, until }),
    onSuccess: async () => {
      setDeferUntil('');
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
    onError: (e) =>
      setError(e instanceof HttpError && (e.status === 409 || e.status === 400 || e.status === 404) && e.body
        ? e.body : `Could not defer this ${claim.status} claim.`),
  });

  const redate = useMutation({
    mutationFn: (date: string) =>
      putJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${claim.id}/redate`, { user, date }),
    onSuccess: async () => {
      setRedateTo('');
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
    onError: (e) =>
      setError(e instanceof HttpError && (e.status === 409 || e.status === 400 || e.status === 404) && e.body
        ? e.body : `Could not re-date this ${claim.status} claim.`),
  });

  // Opening the editor locks the claim for other users until it is saved or cancelled (or the sheet's today
  // changes); the editor stays open on a refusal, whose error shows on the claim, and the server refuses its save.
  const lock = useMutation({
    mutationFn: () =>
      putJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${claim.id}/lock`, { user }),
    onError: (e) =>
      setLockRefused(claim.id, e instanceof HttpError && (e.status === 409 || e.status === 400 || e.status === 403 || e.status === 404) && e.body
        ? e.body : `Could not open this ${claim.status} claim for editing.`),
  });

  const split = useMutation({
    mutationFn: (amount: string) =>
      postJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${claim.id}/split`, { user, amount }),
    onSuccess: async () => {
      setSplitAmount('');
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
    onError: (e) =>
      setError(e instanceof HttpError && (e.status === 409 || e.status === 400 || e.status === 404) && e.body
        ? e.body : `Could not split this ${claim.status} claim.`),
  });

  return (
    <li data-testid={`claim-row-${claim.id}`}>
      <input
        type="checkbox"
        data-testid="claim-select"
        checked={selected}
        onChange={(e) => setSelected(sheetId, claim.id, e.target.checked)}
      />{' '}
      <span data-testid="claim-amount">{claim.amount}</span>{' '}
      <span data-testid="claim-date">{claim.date}</span>{' '}
      <span data-testid="claim-note">{claim.note}</span>{' '}
      <span data-testid="claim-number">{claim.number ?? ''}</span>{' '}
      Corrects <span data-testid="claim-corrects">{claim.corrects ?? ''}</span>{' '}
      <span data-testid="claim-status">{claim.status}</span>{' '}
      <span data-testid="claim-opened-by">{claim.openedBy ?? ''}</span>{' '}
      <span data-testid="claim-due">{claimDue(claim, rate, floor, late)}</span>{' '}
      Due by <span data-testid="claim-due-by">{dueBy(claim)}</span>{' '}
      Overdue <span data-testid="claim-overdue">{overdue(claim, today) ? 'yes' : 'no'}</span>{' '}
      Period <span data-testid="claim-period">{period?.name ?? ''}</span>{' '}
      Late entry <span data-testid="claim-late-entry">{claim.lateEntry ? 'yes' : 'no'}</span>{' '}
      Stated <span data-testid="claim-stated">{claim.stated ? 'yes' : 'no'}</span>{' '}
      Deferred <span data-testid="claim-deferred">{claim.deferred ? 'yes' : 'no'}</span>{' '}
